function vals(p) {
    if (Array.isArray(p)) return p;
    if (p && typeof p === "object") {
        if (p.value !== undefined) return vals(p.value);
        if (p.data !== undefined) return vals(p.data);
        const k = Object.keys(p);
        if (k.length === 1) return vals(p[k[0]]);
        const num = s => { const m = String(s).match(/(\d+)$/); return m ? +m[1] : 0; };
        return k.sort((a, b) => num(a) - num(b)).map(x => p[x]);
    }
    return [p];
}
const v = vals(msg.payload).map(x => Number(x) & 0xFFFF);
if (v.length < 332) { node.status({fill:"yellow",shape:"ring",text:"ได้ " + v.length + " ค่า"}); node.warn(msg.payload); return null; }
const d32 = i => v[i] + v[i + 1] * 65536;
const total = d32(322), ng = v[60];
const out = {
    total, ng, ok: Math.max(0, total - ng),
    rate: d32(330) / 10, ccdNg: d32(300), ccdOk: v[320],
    status: v[0], statusText: { 1: "OP", 2: "EG", 3: "SV" }[v[0]] || ("?" + v[0]),
    time: new Date().toLocaleString("en-GB")
};
flow.set("sb01", out);
node.status({ fill: "green", shape: "dot", text: out.statusText + " | Total " + total + " NG " + ng + " | " + out.rate + "%" });
return { topic: "SB01", payload: out };
